                ww=w
                while jj+ww<=W and all(I[i+h2][jj+ww2]==c for h2 in range(h) for ww2 in range(ww+1)):
                    ww+=1
                if ww==w: break
                jj+=ww-w
                w=ww; j=jj
            if h>=3 and w>=2:
                R.append((h,w,i,j,c))
